const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point1 = ee.Geometry.Point([-79.198692, 43.244129]);
  const point2 = ee.Geometry.Point([-79.069485, 43.263113]);
  const date = '2021-02-04';

  // 2. Data Acquisition - Sentinel-2 for NDVI
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  const collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filterBounds(ee.Geometry.Point([-79.1340885, 43.253621])) // Center point
    .map(maskS2clouds);

  // Check if collection has data
  const collSize = collection.size().getInfo();
  if (collSize === 0) {
    console.log(`Images found: ${collSize}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // Get single image for the date
  const image = collection.first();

  // Calculate NDVI
  const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');

  // Extract NDVI values at both points
  const ndvi1 = ndvi.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point1,
    scale: 100,
    maxPixels: 1e9
  }).get('NDVI');

  const ndvi2 = ndvi.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point2,
    scale: 100,
    maxPixels: 1e9
  }).get('NDVI');

  // Get pixel counts to check validity
  const count1 = ndvi.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point1.buffer(100),
    scale: 100,
    maxPixels: 1e9
  }).get('NDVI');

  const count2 = ndvi.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: point2.buffer(100),
    scale: 100,
    maxPixels: 1e9
  }).get('NDVI');

  const [val1, val2, cnt1, cnt2] = await Promise.all([
    ndvi1.getInfo(), ndvi2.getInfo(), count1.getInfo(), count2.getInfo()
  ]);

  console.log(`Images: ${collSize}, Point1 NDVI: ${val1?.toFixed(3)} (px: ${cnt1}), Point2 NDVI: ${val2?.toFixed(3)} (px: ${cnt2})`);

  // Check for no valid pixels
  if ((cnt1 === 0 || cnt2 === 0) || (val1 === null && val2 === null)) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (val1 === null || val2 === null || isNaN(val1) || isNaN(val2)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare NDVI values - point1 appears greener if NDVI1 > NDVI2
  if (val1 > val2) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
